package module

import (
	"bytes"
	"testing"
)

// TestParseModule_MetadataSources covers T03 B2/B3: parseModule now models the
// metadata_sources config slot (scan-library previously DROPPED it). It is a
// pure function, so a single-module table test is the preferred form. Cases:
// (a) the seeded TV config yields the tv-parser -> kinopoisk -> tmdb chain at
// priorities 1/2/3, each enabled; (b) a config with no metadata_sources yields
// an empty slice without error; (c) a source's opaque options round-trip
// verbatim as json.RawMessage. A parseModule that still DROPPED the slot fails
// case (a) at len==3 (BUG CATCH).
func TestParseModule_MetadataSources(t *testing.T) {
	cases := []struct {
		name   string
		config string
		check  func(*testing.T, Module)
	}{
		{
			name:   "seeded_tv_chain_tv_parser_first",
			config: tvConfigJSON,
			check: func(t *testing.T, m Module) {
				if len(m.MetadataSources) != 4 {
					t.Fatalf("MetadataSources len = %d, want 4: %+v", len(m.MetadataSources), m.MetadataSources)
				}
				want := []struct {
					plugin   string
					priority int
					auth     string
				}{
					{"tv-parser", 1, ""},
					{"kinopoisk", 2, "CLIENT"},
					{"tmdb", 3, "SERVER"},
					{"frame-grabber", 4, ""},
				}
				for i, w := range want {
					got := m.MetadataSources[i]
					if got.PluginID != w.plugin || got.Priority != w.priority ||
						!got.Enabled || got.AuthMode != w.auth || got.CapabilityID != "default" {
						t.Errorf("source[%d] = {plugin=%q cap=%q pri=%d en=%v auth=%q}, "+
							"want {plugin=%q cap=default pri=%d en=true auth=%q}",
							i, got.PluginID, got.CapabilityID, got.Priority, got.Enabled, got.AuthMode,
							w.plugin, w.priority, w.auth)
					}
				}
			},
		},
		{
			name:   "no_metadata_sources_yields_empty_slice",
			config: `{"scanner":{"plugin_id":"base-scanner","capability_id":"default","options":{}}}`,
			check: func(t *testing.T, m Module) {
				if len(m.MetadataSources) != 0 {
					t.Fatalf("MetadataSources = %d, want empty: %+v", len(m.MetadataSources), m.MetadataSources)
				}
				// Scanner slot still parses (parseModule did not regress).
				if m.Scanner.PluginID != "base-scanner" || m.Scanner.CapabilityID != "default" {
					t.Errorf("scanner = %+v, want base-scanner/default", m.Scanner)
				}
			},
		},
		{
			name: "opaque_options_roundtrip_as_raw_message",
			config: `{"scanner":{"plugin_id":"base-scanner","capability_id":"default","options":{}},` +
				`"metadata_sources":[{"plugin_id":"x","capability_id":"default","priority":1,"enabled":true,"options":{"language":"ru","flag":true}}]}`,
			check: func(t *testing.T, m Module) {
				if len(m.MetadataSources) != 1 {
					t.Fatalf("MetadataSources len = %d, want 1", len(m.MetadataSources))
				}
				want := []byte(`{"language":"ru","flag":true}`)
				if !bytes.Equal(m.MetadataSources[0].Options, want) {
					t.Errorf("options = %s, want %s (opaque round-trip)", m.MetadataSources[0].Options, want)
				}
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m, err := parseModule("tv", "tv", 1, []byte(tc.config))
			if err != nil {
				t.Fatalf("parseModule: %v", err)
			}
			tc.check(t, m)
		})
	}
}
